  static void ProbeProcess(string root){string old=Environment.GetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE");try{Environment.SetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE","success");var f=new Fixture(root,"探针 空格",false);Put(Path.Combine(f.Game,"jre64","bin","placeholder"),"fixture");File.Copy(Assembly.GetExecutingAssembly().Location,Path.Combine(f.Game,"jre64","bin","java.exe"));f.Engine.TestMode=false;var before=Tree(f.Game);var row=f.Create();string[] observed=File.ReadAllLines(Path.Combine(row.RuntimeHome,"synthetic-probe.receipt"));Check(observed.Length==6&&observed[1]=="-Duser.home="+row.RuntimeHome&&observed[3]==Path.Combine(row.GamePath,"OrangeLauncherRuntime","environment","OrangeEnvironment.jar")&&observed[5]==row.GamePath,"hidden probe preserves exact arguments through spaces and Chinese paths");Check(Same(before,Tree(f.Game)),"API probe runs against copied files without changing original game");
    Environment.SetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE","failure");var bad=new Fixture(root,"probe-failure",false);Put(Path.Combine(bad.Game,"jre64","bin","placeholder"),"fixture");File.Copy(Assembly.GetExecutingAssembly().Location,Path.Combine(bad.Game,"jre64","bin","java.exe"));bad.Engine.TestMode=false;Refuses(()=>bad.Create(),"unsupported API probe exit prevents publication");Check(!Directory.Exists(Path.Combine(bad.Root,"snapshot"))&&bad.Store.Bound("Sandbox/Original")==null,"unsupported probe removes only unregistered snapshot and creates no binding");
   }finally{Environment.SetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE",old);}}
  static int SyntheticProbe(string[] args){if(args.Length!=6||args[2]!="-cp"||args[4]!="ozl.environment.EnvironmentProbe"||!args[1].StartsWith("-Duser.home="))return 91;string home=args[1].Substring(12);if(!Directory.Exists(home)||!File.Exists(args[3])||Path.GetFileName(args[3])!="OrangeEnvironment.jar")return 92;File.WriteAllLines(Path.Combine(home,"synthetic-probe.receipt"),args);Console.Write(new string('x',20000));string mode=Environment.GetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE");if(mode=="wait-for-cancel")Thread.Sleep(15000);return mode=="failure"?13:0;}
