   Environment.SetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE","failure");using(var controller=new ModernController(f.Game,f.User,f.Data,true)){typeof(ModernController).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,f.Engine);var plan=f.Store.Preview("Sandbox/Original");Check(plan.ready,"unsupported API fixture still passes metadata sizing before its runtime contract check");Exception failure=null;try{controller.Execute("environmentCreate",new Dictionary<string,object>{{"saveId","Sandbox/Original"},{"destination",Path.Combine(f.Root,"never-copied")},{"name","unsupported"},{"stamp",plan.stamp}});}catch(Exception error){failure=error;}Check(failure!=null&&failure.Message.Contains("这个游戏版本暂不支持快照"),"actual controller rejects unsupported source API before starting the full game copy");Check(!Directory.Exists(Path.Combine(f.Root,"never-copied"))&&!Directory.GetDirectories(f.Root,"*.partial-*").Any()&&!File.Exists(Path.Combine(f.Data,"save-environments","index.json")),"unsupported source never creates staging, a snapshot or a registered binding");}
   Environment.SetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE","wait-for-cancel");using(var cancellation=new CancellationTokenSource()){cancellation.CancelAfter(250);var watch=Stopwatch.StartNew();Refuses(()=>Call("CheckSource",f.Engine,cancellation.Token),"source probe responds to cancellation without continuing into copying");Check(watch.ElapsedMilliseconds<8000,"cancelled source probe terminates its hidden synthetic child within the bounded cancellation window");}Check(Same(game,Tree(f.Game))&&Same(user,Tree(f.User))&&before.SequenceEqual(Directory.GetDirectories(temporary,"ozl-env-probe-*").OrderBy(path=>path)),"failed and cancelled source probes preserve originals and clean only their owned temporary files");
  }finally{Environment.SetEnvironmentVariable("OZL_RUNTIME_FIXTURE_PROBE",previous);}}
